class PermissionRequest(DeclaredFamily, affix='PermissionRequest'):

    def __init__(self, controller):
        self.controller = controller
        self.future = asyncio.get_running_loop().create_future()
        self._projections = {}
        self.future.add_done_callback(self._completed)

    @property
    def pending(self):
        return not self.future.done()

    @property
    @abstractmethod
    def options(self) -> list[Answer]:
        ...

    @property
    @abstractmethod
    def presentation(self):
        ...

    def answer(self, binding, answer):
        if self.pending and self.controller.agent.controller.surface is binding:
            if answer is None or any((option.id == answer.id for option in self.options)):
                self.future.set_result(answer)

    def cancel(self):
        if self.pending:
            self.future.set_result(None)

    def watch(self, surface, retire):
        self._projections.setdefault(surface, []).append(retire)

    def projected_on(self, surface):
        """The acquired native projections own their presence."""
        return surface in self._projections

    def detach(self, surface):
        for retire in self._projections.pop(surface, ()):
            retire()

    def _completed(self, future):
        self.controller.requests.discard(self)
        for surface in tuple(self._projections):
            self.detach(surface)

    async def wait(self, timeout):
        try:
            return await asyncio.wait_for(self.future, timeout)
        except TimeoutError:
            return None

class ToolPermissionRequest(PermissionRequest):

    def __init__(self, controller, options, tool_call):
        super().__init__(controller)
        self._options = [Answer(option.name, option.option_id, option.kind) for option in options]
        self._presentation = PermissionPresentation.from_acp(tool_call)

    @property
    def options(self):
        return self._options

    @property
    def presentation(self):
        return self._presentation

class AttachedSurfaceBinding(SurfaceBinding, MroDispatch):

    def __init__(self, target, events):
        self._target = ref(target)
        self.subscription = target.subscribe_core(events)

    def prepare(self, controller) -> None:
        app = self.target.app
        controller.transcripts = controller.transcripts.with_runtime(app.preparation, app.coordination_access)
        controller.validation = ApplicationValidationOwner(app.render_processes)

    def prepare_terminal(self, state) -> None:
        target = self.target
        if target is not None:
            state.update_size(*target.get_terminal_dimensions())

    async def present_permission(self, request, view) -> None:
        if not request.pending or request.projected_on(view) or (not self.owns(view)) or (request.controller.agent.controller.surface is not self):
            return
        view.refresh_bindings()
        await self.dispatch(request.presentation, view, request)

    @handles(DiffPermissionPresentation)
    async def show_file_permission(self, presentation, view, request):
        from toad.screens.permissions import PermissionReview
        screen = PermissionReview(request, view, presentation.diffs, self)
        app = view.app
        try:
            app.terminal_attention.require(screen)
            app.terminal_attention.notify(f'{view.agent_title} would like to write files', title='Permissions request', sound='question')
            request.watch(view, screen.retire)
            result = await app.push_screen_wait(screen, mode=view.screen.id)
            request.answer(self, result)
        finally:
            app.terminal_attention.release(screen)
            if request.controller.agent.controller.surface is self:
                view.refresh_bindings()

    @handles(InlinePermissionPresentation)
    async def show_inline_permission(self, presentation, view, request):
        from toad.widgets.acp_content import ACPToolCallContent
        from toad.tool_output import decode_content
        parts = tuple((preview for item in presentation.parts if (preview := decode_content(item).permission_preview()) is not None))

        def answer(answer):
            if request.controller.agent.controller.surface is not self:
                return
            request.answer(self, answer)
            if not view.prompt.ask_queue:
                view.refresh_bindings()
        ask = view.ask(request.options, presentation.title, partial(ACPToolCallContent, parts) if parts else None, answer)

        def retire():
            if view.is_attached:
                view.prompt.remove_ask(ask)
                if view.prompt._ask is None:
                    view.refresh_bindings()
        request.watch(view, retire)

    def schedule_terminal_presentation(self, controller):
        if (target := self.target) is not None:
            target.call_later(controller.start_terminal_presentation, target)

    def close(self) -> None:
        if (target := self.target) is not None:
            target.retire_core(self.subscription)
        else:
            self.subscription.close()

    @property
    def target(self):
        return self._target()

    def post(self, message):
        target = self.target
        return target.post_message(message) if target is not None else False

    def publish_terminal(self, controller, terminal_id, execution):
        from toad.widgets.terminal_tool import TerminalTool
        return self.post(TerminalTool.Projection(self, controller, terminal_id, execution))

    def owns_terminal(self, projection, target):
        """Same original surface, controller lifetime and acquired address."""
        if not self.owns(target):
            return False
        return projection.controller.owner.owns_terminal_projection(self, projection)

    async def present_terminal(self, projection, target):
        if not self.owns_terminal(projection, target):
            return
        from toad.widgets.terminal_tool import TerminalTool
        if (existing := target.query_one_optional(f'#{projection.terminal_id}', TerminalTool)):
            if existing.execution is projection.execution:
                return
            await existing.remove()
            if not self.owns_terminal(projection, target):
                return
        terminal = TerminalTool(projection.execution, id=projection.terminal_id)
        await target.post(terminal)
        if not self.owns_terminal(projection, target):
            await terminal.remove()

class ContextProjection(MroDispatch):
    """A leaf projection returns display data rather than mutating an event."""

    def consume_handlers_sync(self, value, handlers, *args, **kwargs):
        return next(iter(handlers))(value, *args, **kwargs)

@dataclass
class PermissionPresentation(DeclaredFamily, affix='PermissionPresentation'):
    priority = 0
    title: str

    @classmethod
    def from_acp(cls, tool_call):
        """Decode the external ACP choice once, at request admission."""
        content = tool_call.content or []
        title = tool_call.title or ''
        for member in sorted(cls.members_with(cls), key=lambda member: member.priority, reverse=True):
            if (presentation := member.admit(tool_call.kind, title, content)) is not None:
                return presentation
        raise ValueError('No permission presentation admitted the ACP request')

    @classmethod
    @abstractmethod
    def admit(cls, kind, title, content):
        ...

class DiffPermissionPresentation(PermissionPresentation):

    def __init__(self, title, diffs):
        super().__init__(title)
        self.diffs = diffs

    @classmethod
    def admit(cls, kind, title, content):
        if kind != 'edit' and (not all((isinstance(item, FileEditToolCallContent) for item in content))):
            return None
        records = [item for item in content if isinstance(item, FileEditToolCallContent)]
        diffs = [(item.path, item.path, item.old_text, item.new_text) for item in records]
        return cls(title, diffs) if diffs else None

@dataclass
class InlinePermissionPresentation(PermissionPresentation):
    priority = -1
    parts: tuple[ContentToolCallContent | FileEditToolCallContent | TerminalToolCallContent, ...]

    @classmethod
    def admit(cls, kind, title, content):
        return cls(title, tuple(content))

class TerminalOutcome(DeclaredFamily, affix='TerminalOutcome'):
    finished = False
    successful = False

    def exit_status(self) -> protocol.TerminalExitStatus | None:
        return None

class TerminalCompletion(TerminalOutcome):
    finished = True

    @abstractmethod
    def wait_response(self) -> protocol.WaitForTerminalExitResponse:
        ...

    @property
    @abstractmethod
    def label(self) -> str:
        ...

    @classmethod
    def capture(cls, original: ChildOutcome) -> TerminalCompletion:
        return _TerminalCompletionDecoder(original).completion

@dataclass(frozen=True)
class FailedTerminalOutcome(TerminalOutcome):
    error: BaseException
    finished = True

@work
async def request_permissions(self, request) -> None:
    await request.controller.agent.controller.surface.present_permission(request, self)

class TerminalTool(Terminal, MroDispatch):

    @dataclass
    class Projection(Message):
        """A native render request borrows its original acquired resources."""
        binding: AttachedSurfaceBinding
        controller: TerminalController
        terminal_id: str
        execution: TerminalExecution
    DEFAULT_CSS = '\n    TerminalTool {\n        height: auto;\n        border: panel $text-primary;\n    }\n    '

    def __init__(self, execution: TerminalExecution, *, id: str) -> None:
        self.execution = execution
        super().__init__(id=id, size=(execution.state.width, execution.state.height))
        self.border_title = Content(str(execution.command))

    def on_mount(self) -> None:
        super().on_mount()
        self.execution.attach(self)

    def on_unmount(self) -> None:
        self.execution.detach(self)

    def resize_process(self, width: int, height: int) -> None:
        self.execution.update_size(width, height)

    def present_execution(self) -> None:
        self.project_state(None, None)
        self.dispatch_sync(self.execution.outcome)

    @handles(RunningTerminalOutcome, UnstartedTerminalOutcome, RetiredTerminalOutcome)
    def present_pending(self, outcome) -> None:
        """These original outcomes have no completion border to draw."""

    @handles(TerminalCompletion)
    def present_completion(self, outcome) -> None:
        self.finalize()
        self.set_class(outcome.successful, '-success')
        self.set_class(not outcome.successful, '-error')
        if not outcome.successful:
            self.border_title = Content(f'{self.execution.command} [{outcome.label}]')

    @handles(FailedTerminalOutcome)
    def present_failure(self, outcome) -> None:
        self.finalize()
        self.set_class(True, '-error')
        self.border_title = Content(f'{self.execution.command} [{outcome.error}]')

def present_execution(self) -> None:
    self.project_state(None, None)
    self.dispatch_sync(self.execution.outcome)

class DurableTurn(MroDispatch):

    def __init__(self, attempts: AttemptStore, fence, pointer_revision, input_id):
        self.attempts = attempts
        self.fence = fence
        self.pointer_revision = pointer_revision
        self.input_id = input_id

    @contextmanager
    def using_attempts(self, attempts):
        """Borrow only this operation's connection; keep the original fence owner."""
        original = self.attempts
        self.attempts = attempts
        try:
            yield
        finally:
            self.attempts = original

    async def consume_handlers(self, event, handlers):
        return await Coordination.run_async(self.attempts.session.path, partial(self.observe_owned, event, handlers))

    def observe_owned(self, event, handlers, resource):
        """Consume one native observation through joined, worker-owned SQLite."""
        with self.using_attempts(resource.attempts):
            return self.consume_handlers_sync(event, handlers)

    @property
    def current(self):
        return type(self.attempts.require_fence(self.fence)[1].lifecycle)

    @property
    def model_started(self):
        return self.current.has_model_context

    def advance(self, state):
        if state is self.current:
            return
        result = self.attempts.advance(self.fence, state, expected_pointer_revision=self.pointer_revision, progress=True).value
        self.fence = result.fence

    @handles(pi.Response)
    def accepted(self, event):
        if event.id == 'native-prompt' and event.success and self.current.starting:
            self.advance(PromptAcceptedAttempt)

    @handles(pi.ContextCommitted)
    def context(self, event):
        if event.input_id != self.input_id or self.model_started:
            return
        if self.current.starting:
            self.advance(PromptAcceptedAttempt)
        self.advance(ModelRunningAttempt)

    @handles(NativePhaseChanged)
    def excursion(self, event):
        if self.model_started:
            self.dispatch_sync(event.phase)

    @handles(ModelWaitPhase)
    def model(self, phase):
        self.advance(ModelRunningAttempt)

    @handles(ToolRunningPhase)
    def tool(self, phase):
        self.advance(ToolRunningAttempt)

    @handles(CompactionPhase)
    def compaction(self, phase):
        self.advance(CompactionAttempt)

    def finish(self):
        """Native child is reaped and any explicit owner effect has completed."""
        if not self.model_started:
            raise IdentityConflict('native completion lacks model progress')
        self.fence = self.attempts.advance(self.fence, SettlingAttempt, expected_pointer_revision=self.pointer_revision, backend_done=True, process_dead=True, progress=True).value.fence
        return self.fence

    def fail_unknown(self):
        """Retire the reaped local backend without granting acceptance or replay.

        The caller holds the live registry owner boundary. Native execution has
        returned through child/tool cleanup; possible remote effects stay UNKNOWN.
        Coordination owns the atomic replay/finality/slot mutation.
        """
        return self.attempts.fail_unknown(self.fence, expected_pointer_revision=self.pointer_revision).value

    def fail_terminal(self):
        """Settle the corroborated failed input after its native child is reaped."""
        final = self.attempts.advance(self.fence, self.current, expected_pointer_revision=self.pointer_revision, backend_done=True, process_dead=True, reason_code='native_terminal_failure').value
        return self.attempts.settle_nonpublication(final.fence, expected_pointer_revision=final.snapshot.pointer_revision, outcome=AttemptFailedAttempt(), reason_code='native_terminal_failure').value

def observe_owned(self, event, handlers, resource):
    """Consume one native observation through joined, worker-owned SQLite."""
    with self.using_attempts(resource.attempts):
        return self.consume_handlers_sync(event, handlers)

class MroDispatch:
    """Invoke specific handlers before base handlers; consumer overrides win.

    The method declarations are the authority. No global registry, registration
    order, or event-name roster participates in dispatch. A diamond ancestor is
    visited once by Python's MRO. A returned replacement flows to later handlers.
    """

    def handlers_for(self, value: Any):
        methods: dict[str, Any] = {}
        for owner in type(self).__mro__:
            for name, method in vars(owner).items():
                methods.setdefault(name, method)
        for capability in type(value).__mro__:
            for name, method in methods.items():
                if capability in getattr(method, '__handled_classes__', ()):
                    yield getattr(self, name)

    async def dispatch(self, value: Any) -> Any:
        handlers = tuple(self.handlers_for(value))
        if not handlers:
            return value
        return await self.consume_handlers(value, handlers)

    async def consume_handlers(self, value: Any, handlers: Iterable[Handler]) -> Any:
        """Consume the selected declarations inside the consumer's resource lifetime."""
        for handler in handlers:
            value = self.replace_value(value, await handler(value))
        return value

    def dispatch_sync(self, value: Any) -> Any:
        """Consume saved presentation facts without introducing an event loop."""
        return self.consume_handlers_sync(value, self.handlers_for(value))

    def consume_handlers_sync(self, value: Any, handlers: Iterable[Handler]) -> Any:
        for handler in handlers:
            value = self.replace_value(value, handler(value))
        return value

    @staticmethod
    def replace_value(value: Any, replacement: Any) -> Any:
        if replacement is None:
            return value
        if type(replacement) is not type(value):
            raise TypeError('A dispatch replacement must preserve event identity')
        return replacement

